/**
 * Returns ISO-8601 formatted time converted to UTC, truncated to the seconds place
 * @param calendar
 * @return
 */
private static String doFormatDate(Calendar calendar) {
    return calendar.toInstant().truncatedTo(ChronoUnit.SECONDS).toString();
}
